def intro(n,k,t,d,a=''):return f'<section class="page-intro wrap">{label(n,k)}<h1>{t}</h1><p class="intro-text">{d}</p><div class="actions">{a}</div></section>'
def fig(src,alt,cap,phone=False):return f'<figure class="{"phone-shot" if phone else "screen-shot"}"><img src="/assets/{src}" alt="{alt}" loading="lazy" decoding="async" {"width=660 height=1434" if phone else "width=1480 height=920"}><figcaption>{cap}</figcaption></figure>'
